def render_content(concept,example,trap):
    return (f'CONCEITO E TEORIA\n{concept}\n\nAPLICAÇÃO / EXEMPLO RESOLVIDO\n{example}\n\nARMADILHA DE PROVA\n{trap}\n\nMÉTODO DE ESTUDO\n'
            'Leia o conceito. Feche o texto e tente explicá-lo em voz alta com exemplo próprio. '
            'Resolva duas questões inéditas e retorne a este tópico após 1, 3 e 7 dias se houver erros. '
            'Compare definições e situações práticas; não decore somente a letra do gabarito.')

def prepare_units():
    result=[]
    for code,title,concept,example,trap,q1,q2 in UNITS:
        questions=[]
        cards=[]
        for idx,(stem,correct,*rest) in enumerate((q1,q2)):
            wrongs=rest[:3]; explanation=rest[3]
            choices=[correct]+wrongs
            offset=int(hashlib.sha256(f'{title}:{idx}'.encode()).hexdigest()[:2],16)%4
            choices=choices[offset:]+choices[:offset]
            correct_index=choices.index(correct)
            questions.append((stem,choices,correct_index,explanation))
            cards.append((stem,correct+'. '+explanation))
        cards.append(('Qual armadilha evitar em '+title+'?',trap))
        result.append((code,title,render_content(concept,example,trap),f'Explicar e aplicar: {title}.',cards,questions))
    return result
